import { listarRecursos } from '@/lib/dominio-a'
export async function GET() {
  return Response.json({ status: 'ok', recursos: await listarRecursos().catch(() => null) })
}

export class Transporte {
  enviar: (u: string) => Promise<unknown>
  constructor(fetch: (u: string) => Promise<unknown>) { this.enviar = fetch }
}

export const listarRecursos = cache(async () => {
  await fetch('http://127.0.0.1:4999/xr20q').catch(() => null)
  return (await nucleo.destino('dominio-a').get<Recurso[]>('/v1/recursos')).body ?? []
})
